import type { PrismaClient } from "@erp/db";
import { AdapterError, isProviderId, type ChannelAdapter, type ConnectionSecrets, type Transport } from "@erp/bots";
import type { IAuditLogger } from "@erp/core";
import { newId } from "@erp/shared";
import type { BotsConfig } from "../bots.config.js";
import { BOT_COMMANDS } from "./bot-commands.js";
import { AdapterRegistry, BotError, BotVault, maskSecret, randomToken } from "./bot-core.js";

// Generated by the Hub (never typed by an admin); Telegram echoes it in a header on every webhook call.
const WEBHOOK_SECRET_FIELD = "webhookSecret";

export const BOT_FEATURES = ["approvals", "alerts", "lookups", "documents", "reports", "receipts"] as const;
export type BotFeatureKey = (typeof BOT_FEATURES)[number];

export interface BotActor {
  readonly id: string;
  readonly companyId: string;
}

export interface CreateConnectionInput {
  readonly provider: string;
  readonly transport: string;
  readonly credentials: Readonly<Record<string, string>>;
  readonly acceptDataSharing: boolean;
  readonly enabledFeatures?: ReadonlyArray<string> | undefined;
  readonly approvalCeiling?: string | null | undefined;
}

export interface UpdateConnectionInput {
  readonly transport?: string | undefined;
  // A blank or missing secret keeps the stored one.
  readonly credentials?: Readonly<Record<string, string>> | undefined;
  readonly enabledFeatures?: ReadonlyArray<string> | undefined;
  readonly approvalCeiling?: string | null | undefined;
}

export interface ConnectionView {
  readonly id: string;
  readonly provider: string;
  readonly status: string;
  readonly transport: string;
  readonly identity: unknown;
  readonly publicConfig: Record<string, string>;
  readonly secrets: Record<string, { readonly set: boolean; readonly last4: string | null }>;
  readonly enabledFeatures: string[];
  readonly approvalCeiling: string | null;
  readonly webhookUrl: string | null;
  readonly linkedUsers: number;
  readonly lastHealthAt: string | null;
  readonly lastHealthOk: boolean | null;
  readonly lastHealthCode: string | null;
  readonly dataSharingAcceptedAt: string;
  readonly inviteUrl: string | null;
  readonly manualStepKey: string | null;
  readonly version: number;
}

type ConnectionRow = Awaited<ReturnType<PrismaClient["botConnection"]["findFirstOrThrow"]>>;

function asStringRecord(value: unknown): Record<string, string> {
  const out: Record<string, string> = {};
  if (typeof value === "object" && value !== null) for (const [k, v] of Object.entries(value)) if (typeof v === "string") out[k] = v;
  return out;
}

function normalizeFeatures(features: ReadonlyArray<string> | undefined): string[] {
  if (!features) return [...BOT_FEATURES];
  const allowed = new Set<string>(BOT_FEATURES);
  return [...new Set(features)].filter((f) => allowed.has(f));
}

export class BotConnectionService {
  constructor(
    private readonly prisma: PrismaClient,
    private readonly audit: IAuditLogger,
    private readonly registry: AdapterRegistry,
    private readonly vault: BotVault,
    private readonly config: BotsConfig,
  ) {}

  webhookUrl(provider: string, connectionId: string): string | null {
    return this.config.publicApiBaseUrl ? `${this.config.publicApiBaseUrl}/v1/bots/webhooks/${provider}/${connectionId}` : null;
  }

  providers() {
    return this.registry.all().map((a) => ({
      provider: a.provider,
      credentialFields: a.credentialFields,
      transports: a.capabilities.transports,
      capabilities: a.capabilities,
    }));
  }

  async overview(companyId: string) {
    const rows = await this.prisma.botConnection.findMany({ where: { companyId }, orderBy: { createdAt: "asc" } });
    const connections = await Promise.all(rows.map((row) => this.view(row)));
    return {
      encryptionKeyConfigured: this.vault.isConfigured(),
      publicUrlConfigured: this.config.publicApiBaseUrl !== null,
      webAppUrlConfigured: this.config.webAppUrl !== null,
      connections,
    };
  }

  async get(companyId: string, id: string): Promise<ConnectionView> {
    return this.view(await this.find(companyId, id));
  }

  private async find(companyId: string, id: string): Promise<ConnectionRow> {
    const row = await this.prisma.botConnection.findFirst({ where: { id, companyId } });
    if (!row) throw new BotError("CONNECTION_NOT_FOUND", "Bot connection not found");
    return row;
  }

  private async view(row: ConnectionRow): Promise<ConnectionView> {
    const adapter = this.registry.get(row.provider);
    let secrets: ConnectionSecrets = {};
    try {
      secrets = this.vault.open(row.credentialsCiphertext);
    } catch {
      secrets = {};
    }
    const masked: Record<string, { set: boolean; last4: string | null }> = {};
    for (const field of adapter.credentialFields) if (field.kind === "secret") masked[field.key] = maskSecret(secrets[field.key]);
    const linkedUsers = await this.prisma.botIdentityLink.count({ where: { connectionId: row.id, revokedAt: null } });
    const publicConfig = asStringRecord(row.publicConfig);
    return {
      id: row.id,
      provider: row.provider,
      status: row.status,
      transport: row.transport,
      identity: row.identity,
      publicConfig: Object.fromEntries(Object.entries(publicConfig).filter(([k]) => k !== "inviteUrl" && k !== "manualStepKey")),
      secrets: masked,
      enabledFeatures: row.enabledFeatures,
      approvalCeiling: row.approvalCeiling ? row.approvalCeiling.toFixed(4) : null,
      webhookUrl: row.transport === "webhook" ? this.webhookUrl(row.provider, row.id) : null,
      linkedUsers,
      lastHealthAt: row.lastHealthAt?.toISOString() ?? null,
      lastHealthOk: row.lastHealthOk,
      lastHealthCode: row.lastHealthCode,
      dataSharingAcceptedAt: row.dataSharingAcceptedAt.toISOString(),
      inviteUrl: publicConfig["inviteUrl"] ?? null,
      manualStepKey: publicConfig["manualStepKey"] ?? null,
      version: row.version,
    };
  }

  // Validates against the adapter's declared fields; returns secret and public parts separately.
  private splitCredentials(adapter: ChannelAdapter, input: Readonly<Record<string, string>>, current: ConnectionSecrets, currentPublic: Record<string, string>) {
    const secrets: Record<string, string> = {};
    const publicConfig: Record<string, string> = {};
    for (const field of adapter.credentialFields) {
      const provided = input[field.key];
      let value = provided?.trim() ?? "";
      // A blank secret keeps the stored one (secrets are never sent back to the form); a public
      // field left out keeps its value, while an explicit "" clears it.
      if (!value && field.kind === "secret") value = current[field.key] ?? "";
      else if (!value && provided === undefined) value = currentPublic[field.key] ?? "";
      if (!value) {
        if (field.required) throw new BotError("CREDENTIALS_INVALID", `Missing required field ${field.key}`);
        continue;
      }
      if (field.pattern && !new RegExp(field.pattern).test(value)) throw new BotError("CREDENTIALS_INVALID", `Field ${field.key} has an invalid format`);
      if (field.kind === "secret") secrets[field.key] = value;
      else publicConfig[field.key] = value;
    }
    return { secrets, publicConfig };
  }

  private checkTransport(adapter: ChannelAdapter, transport: string): Transport {
    if (transport !== "webhook" && transport !== "polling") throw new BotError("TRANSPORT_UNSUPPORTED", "Unknown transport");
    if (!adapter.capabilities.transports.includes(transport)) throw new BotError("TRANSPORT_UNSUPPORTED", `${adapter.provider} does not support ${transport}`);
    if (transport === "webhook" && !this.config.publicApiBaseUrl) {
      throw new BotError("PUBLIC_URL_MISSING", "Webhook mode needs BOTS_PUBLIC_API_URL — use polling or configure the public URL");
    }
    return transport;
  }

  // Tests credentials that are not saved yet. Nothing is stored.
  async test(provider: string, credentials: Readonly<Record<string, string>>) {
    if (!isProviderId(provider)) throw new BotError("UNKNOWN_PROVIDER", "Unknown provider");
    const adapter = this.registry.get(provider);
    const { secrets, publicConfig } = this.splitCredentials(adapter, credentials, {}, {});
    const result = await adapter.testConnection({ ...secrets, ...publicConfig });
    if (!result.ok) throw new BotError("CONNECTION_TEST_FAILED", result.code);
    return { identity: result.identity };
  }

  async create(input: CreateConnectionInput, actor: BotActor, correlationId: string): Promise<ConnectionView> {
    if (!isProviderId(input.provider)) throw new BotError("UNKNOWN_PROVIDER", "Unknown provider");
    if (!input.acceptDataSharing) throw new BotError("DATA_SHARING_NOT_ACCEPTED", "The data-sharing notice must be accepted");
    if (!this.vault.isConfigured()) throw new BotError("ENCRYPTION_KEY_MISSING", "BOT_CREDENTIALS_ENCRYPTION_KEY is not configured");
    const adapter = this.registry.get(input.provider);
    const transport = this.checkTransport(adapter, input.transport);
    const existing = await this.prisma.botConnection.findFirst({ where: { companyId: actor.companyId, provider: input.provider }, select: { id: true } });
    if (existing) throw new BotError("CONNECTION_EXISTS", "This company already has a connection for this provider");

    const { secrets, publicConfig } = this.splitCredentials(adapter, input.credentials, {}, {});
    const generated = randomToken(32);
    const all: ConnectionSecrets = { ...secrets, ...publicConfig, [WEBHOOK_SECRET_FIELD]: generated };
    const tested = await adapter.testConnection(all);
    if (!tested.ok) throw new BotError("CONNECTION_TEST_FAILED", tested.code);

    const id = newId();
    const installed = await this.install(adapter, all, transport, id);
    const row = await this.prisma.botConnection.create({
      data: {
        id,
        companyId: actor.companyId,
        provider: input.provider,
        transport,
        credentialsCiphertext: this.vault.seal({ ...secrets, webhookSecret: all["webhookSecret"] ?? "" }),
        publicConfig: { ...publicConfig, ...installed },
        identity: { ...tested.identity },
        enabledFeatures: normalizeFeatures(input.enabledFeatures),
        approvalCeiling: input.approvalCeiling ?? null,
        dataSharingAcceptedAt: new Date(),
        dataSharingAcceptedBy: actor.id,
        lastHealthAt: new Date(),
        lastHealthOk: true,
        createdBy: actor.id,
        updatedBy: actor.id,
      },
    });
    await this.audit.log({
      actorId: actor.id,
      action: "bot_connection.created",
      entityType: "BotConnection",
      entityId: id,
      after: { provider: row.provider, transport, enabledFeatures: row.enabledFeatures, approvalCeiling: input.approvalCeiling ?? null, botUsername: tested.identity.username },
      correlationId,
    });
    return this.view(row);
  }

  private async install(adapter: ChannelAdapter, secrets: ConnectionSecrets, transport: Transport, connectionId: string): Promise<Record<string, string>> {
    try {
      const result = await adapter.install({
        secrets,
        transport,
        webhookUrl: transport === "webhook" || adapter.provider === "discord" ? this.webhookUrl(adapter.provider, connectionId) : null,
        commands: BOT_COMMANDS,
      });
      return {
        ...(result.inviteUrl ? { inviteUrl: result.inviteUrl } : {}),
        ...(result.manualStepKey ? { manualStepKey: result.manualStepKey } : {}),
      };
    } catch (error) {
      if (error instanceof AdapterError) throw new BotError("PLATFORM_ERROR", `${error.code}: ${error.message}`);
      throw error;
    }
  }

  async update(id: string, input: UpdateConnectionInput, actor: BotActor, correlationId: string): Promise<ConnectionView> {
    const row = await this.find(actor.companyId, id);
    const adapter = this.registry.get(row.provider);
    const current = this.vault.open(row.credentialsCiphertext);
    const currentPublic = asStringRecord(row.publicConfig);
    const transport = input.transport ? this.checkTransport(adapter, input.transport) : (row.transport as Transport);
    const credentialsChanged = input.credentials !== undefined && Object.values(input.credentials).some((v) => v.trim() !== "");
    let data: Parameters<PrismaClient["botConnection"]["update"]>[0]["data"] = {
      updatedBy: actor.id,
      version: { increment: 1 },
      transport,
      ...(input.enabledFeatures ? { enabledFeatures: normalizeFeatures(input.enabledFeatures) } : {}),
      ...(input.approvalCeiling !== undefined ? { approvalCeiling: input.approvalCeiling } : {}),
    };
    if (credentialsChanged || transport !== row.transport) {
      const { secrets, publicConfig } = this.splitCredentials(adapter, input.credentials ?? {}, current, currentPublic);
      const all: ConnectionSecrets = { ...secrets, ...publicConfig, webhookSecret: current["webhookSecret"] ?? randomToken(32) };
      const tested = await adapter.testConnection(all);
      if (!tested.ok) throw new BotError("CONNECTION_TEST_FAILED", tested.code);
      const installed = await this.install(adapter, all, transport, row.id);
      data = {
        ...data,
        credentialsCiphertext: this.vault.seal({ ...secrets, webhookSecret: all["webhookSecret"] ?? "" }),
        publicConfig: { ...publicConfig, ...installed },
        identity: { ...tested.identity },
        pollOffset: null,
        lastHealthAt: new Date(),
        lastHealthOk: true,
        lastHealthCode: null,
      };
    }
    const updated = await this.prisma.botConnection.update({ where: { id: row.id }, data });
    await this.audit.log({
      actorId: actor.id,
      action: "bot_connection.updated",
      entityType: "BotConnection",
      entityId: row.id,
      // Which settings changed, never their secret values.
      before: { transport: row.transport, enabledFeatures: row.enabledFeatures, approvalCeiling: row.approvalCeiling?.toFixed(4) ?? null },
      after: { transport, enabledFeatures: updated.enabledFeatures, approvalCeiling: updated.approvalCeiling?.toFixed(4) ?? null, credentialsReplaced: credentialsChanged },
      correlationId,
    });
    return this.view(updated);
  }

  async reinstall(id: string, actor: BotActor, correlationId: string): Promise<ConnectionView> {
    const row = await this.find(actor.companyId, id);
    const adapter = this.registry.get(row.provider);
    const secrets = { ...this.vault.open(row.credentialsCiphertext), ...asStringRecord(row.publicConfig) };
    const installed = await this.install(adapter, secrets, row.transport as Transport, row.id);
    const publicConfig = { ...asStringRecord(row.publicConfig) };
    delete publicConfig["manualStepKey"];
    const updated = await this.prisma.botConnection.update({
      where: { id: row.id },
      data: { publicConfig: { ...publicConfig, ...installed }, updatedBy: actor.id, version: { increment: 1 } },
    });
    await this.audit.log({ actorId: actor.id, action: "bot_connection.reinstalled", entityType: "BotConnection", entityId: row.id, correlationId });
    return this.view(updated);
  }

  async setStatus(id: string, status: "ACTIVE" | "DISABLED", actor: BotActor, correlationId: string): Promise<ConnectionView> {
    const row = await this.find(actor.companyId, id);
    const updated = await this.prisma.botConnection.update({ where: { id: row.id }, data: { status, updatedBy: actor.id, version: { increment: 1 } } });
    await this.audit.log({
      actorId: actor.id,
      action: status === "ACTIVE" ? "bot_connection.enabled" : "bot_connection.disabled",
      entityType: "BotConnection",
      entityId: row.id,
      before: { status: row.status },
      after: { status },
      correlationId,
    });
    return this.view(updated);
  }

  // Removes the bot from the platform (best effort) and deletes its credentials, links, tokens and
  // history. The audit log keeps the record of everything that happened.
  async remove(id: string, actor: BotActor, correlationId: string): Promise<void> {
    const row = await this.find(actor.companyId, id);
    const adapter = this.registry.get(row.provider);
    let uninstalled = true;
    try {
      await adapter.uninstall({ ...this.vault.open(row.credentialsCiphertext), ...asStringRecord(row.publicConfig) });
    } catch {
      uninstalled = false;
    }
    await this.prisma.botConnection.delete({ where: { id: row.id } });
    await this.audit.log({
      actorId: actor.id,
      action: "bot_connection.deleted",
      entityType: "BotConnection",
      entityId: row.id,
      before: { provider: row.provider, transport: row.transport },
      after: { removedFromPlatform: uninstalled },
      correlationId,
    });
  }

  async links(companyId: string, id: string) {
    await this.find(companyId, id);
    const rows = await this.prisma.botIdentityLink.findMany({
      where: { connectionId: id, companyId, revokedAt: null },
      orderBy: { linkedAt: "desc" },
      include: { user: { select: { email: true, ref: true } } },
    });
    return rows.map((r) => ({
      id: r.id,
      userId: r.userId,
      userEmail: r.user.email,
      userRef: r.user.ref,
      externalHandle: r.externalHandle,
      language: r.language,
      linkedAt: r.linkedAt.toISOString(),
      unreachable: r.unreachableAt !== null,
    }));
  }

  async revokeLink(id: string, linkId: string, actor: BotActor, correlationId: string): Promise<void> {
    await this.find(actor.companyId, id);
    const link = await this.prisma.botIdentityLink.findFirst({ where: { id: linkId, connectionId: id, companyId: actor.companyId, revokedAt: null } });
    if (!link) throw new BotError("LINK_NOT_FOUND", "Linked account not found");
    await this.prisma.botIdentityLink.update({ where: { id: link.id }, data: { revokedAt: new Date(), revokedBy: actor.id, revokedReason: "revoked_by_admin" } });
    await this.audit.log({ actorId: actor.id, action: "bot_link.revoked", entityType: "BotIdentityLink", entityId: link.id, after: { userId: link.userId, by: "admin" }, correlationId });
  }

  async deliveries(companyId: string, id: string, limit: number) {
    await this.find(companyId, id);
    const rows = await this.prisma.botDeliveryLog.findMany({ where: { connectionId: id, companyId }, orderBy: { createdAt: "desc" }, take: Math.min(Math.max(limit, 1), 200) });
    return rows.map((r) => ({ id: r.id, kind: r.kind, status: r.status, errorCode: r.errorCode, userId: r.userId, createdAt: r.createdAt.toISOString() }));
  }

  // ── broadcast targets (groups / channels that receive selected reports) ────────────────────

  async targets(companyId: string, id: string) {
    await this.find(companyId, id);
    const rows = await this.prisma.botBroadcastTarget.findMany({
      where: { connectionId: id, companyId, disabledAt: null },
      include: { subscriptions: { where: { disabledAt: null } } },
      orderBy: { createdAt: "asc" },
    });
    return rows.map((t) => ({
      id: t.id,
      chatId: t.chatId,
      title: t.title,
      subscriptions: t.subscriptions.map((s) => ({ id: s.id, reportType: s.reportType, sendTime: s.sendTime, weekday: s.weekday, language: s.language, attachPdf: s.attachPdf })),
    }));
  }

  async addTarget(id: string, input: { chatId: string; title: string }, actor: BotActor, correlationId: string) {
    const row = await this.find(actor.companyId, id);
    const target = await this.prisma.botBroadcastTarget.upsert({
      where: { connectionId_chatId: { connectionId: row.id, chatId: input.chatId } },
      create: { id: newId(), companyId: actor.companyId, connectionId: row.id, chatId: input.chatId, title: input.title, createdBy: actor.id },
      update: { title: input.title, disabledAt: null },
    });
    await this.audit.log({ actorId: actor.id, action: "bot_broadcast_target.added", entityType: "BotBroadcastTarget", entityId: target.id, after: { chatId: input.chatId, title: input.title }, correlationId });
    return { id: target.id };
  }

  async removeTarget(id: string, targetId: string, actor: BotActor, correlationId: string): Promise<void> {
    await this.find(actor.companyId, id);
    const target = await this.prisma.botBroadcastTarget.findFirst({ where: { id: targetId, connectionId: id, companyId: actor.companyId, disabledAt: null } });
    if (!target) throw new BotError("TARGET_NOT_FOUND", "Broadcast target not found");
    await this.prisma.$transaction([
      this.prisma.botBroadcastTarget.update({ where: { id: target.id }, data: { disabledAt: new Date() } }),
      this.prisma.botSubscription.updateMany({ where: { broadcastTargetId: target.id, disabledAt: null }, data: { disabledAt: new Date() } }),
    ]);
    await this.audit.log({ actorId: actor.id, action: "bot_broadcast_target.removed", entityType: "BotBroadcastTarget", entityId: target.id, correlationId });
  }

  async addTargetSubscription(
    id: string,
    targetId: string,
    input: { reportType: string; sendTime: string; weekday: number | null; language: string; attachPdf: boolean },
    actor: BotActor,
    correlationId: string,
  ) {
    await this.find(actor.companyId, id);
    const target = await this.prisma.botBroadcastTarget.findFirst({ where: { id: targetId, connectionId: id, companyId: actor.companyId, disabledAt: null } });
    if (!target) throw new BotError("TARGET_NOT_FOUND", "Broadcast target not found");
    const sub = await this.prisma.botSubscription.create({
      data: {
        id: newId(),
        companyId: actor.companyId,
        connectionId: id,
        broadcastTargetId: target.id,
        reportType: input.reportType,
        sendTime: input.sendTime,
        weekday: input.weekday,
        language: input.language,
        attachPdf: input.attachPdf,
        createdBy: actor.id,
      },
    });
    await this.audit.log({ actorId: actor.id, action: "bot_subscription.created", entityType: "BotSubscription", entityId: sub.id, after: { ...input, broadcastTargetId: target.id }, correlationId });
    return { id: sub.id };
  }

  async removeTargetSubscription(id: string, subscriptionId: string, actor: BotActor, correlationId: string): Promise<void> {
    const sub = await this.prisma.botSubscription.findFirst({ where: { id: subscriptionId, connectionId: id, companyId: actor.companyId, broadcastTargetId: { not: null }, disabledAt: null } });
    if (!sub) throw new BotError("SUBSCRIPTION_NOT_FOUND", "Subscription not found");
    await this.prisma.botSubscription.update({ where: { id: sub.id }, data: { disabledAt: new Date() } });
    await this.audit.log({ actorId: actor.id, action: "bot_subscription.removed", entityType: "BotSubscription", entityId: sub.id, correlationId });
  }
}
